using System;
using System.Reflection;

class Person { public string Name { get; set; } public int Age { get; set; } public string Hello(string who) { return "Hi " + who + ", I am " + Name; } }

class Program {
    static void Main() {
        Type t = typeof(Person);
        // Reflection: create an instance by type, with no "new Person()" in sight
        object o = Activator.CreateInstance(t);
        t.GetProperty("Name").SetValue(o, "Ada");     // set by string name
        t.GetProperty("Age").SetValue(o, 36);
        foreach (PropertyInfo p in t.GetProperties())  // list members at run time
            Console.WriteLine(p.Name + " : " + p.PropertyType.Name + " = " + p.GetValue(o));
        // invoke a method by name
        object r = t.GetMethod("Hello").Invoke(o, new object[] { "Bob" });
        Console.WriteLine(r);
    }
}

using System;

class Animal { }
class Dog : Animal { }

class Program {
    static void Main() {
        Animal a = new Dog();
        Console.WriteLine("typeof(Animal)  = " + typeof(Animal).Name);   // compile-time
        Console.WriteLine("a.GetType()     = " + a.GetType().Name);      // run-time type
        Console.WriteLine("Type.GetType    = " + Type.GetType("System.Int32").Name);
        Console.WriteLine("missing         = " + (Type.GetType("No.Such.Type") == null ? "null" : "found"));
        // exact-type check vs 'is'
        Console.WriteLine("exact Dog?  " + (a.GetType() == typeof(Dog)));
        Console.WriteLine("exact Animal? " + (a.GetType() == typeof(Animal)));
        Console.WriteLine("is Animal?  " + (a is Animal));               // accepts subclasses
        int? n = 5;
        Console.WriteLine("((int?)5).GetType() = " + n.GetType().Name);  // boxes to Int32
    }
}

using System;
using System.Reflection;

[AttributeUsage(AttributeTargets.Property)]
class MaxLenAttribute : Attribute {
    public int Max { get; private set; }
    public MaxLenAttribute(int max) { Max = max; }   // positional argument
}

class User {
    [MaxLen(5)] public string Name { get; set; }
    [MaxLen(10)] public string Email { get; set; }
    public string Note { get; set; }                 // no attribute
}

class Program {
    static void Main() {
        var u = new User { Name = "Alexander", Email = "a@b.c", Note = "x" };
        // Consume the attribute by reflection: nothing ran until now
        foreach (PropertyInfo p in typeof(User).GetProperties()) {
            var attr = (MaxLenAttribute)p.GetCustomAttribute(typeof(MaxLenAttribute));
            if (attr == null) { Console.WriteLine(p.Name + ": no rule"); continue; }
            string v = (string)p.GetValue(u);
            Console.WriteLine(p.Name + ": '" + v + "' len " + v.Length + " max " + attr.Max
                + (v.Length > attr.Max ? " -> INVALID" : " -> ok"));
        }
    }
}

using System;
using System.Collections.Generic;

class Animal { public string Name = "animal"; }
class Dog : Animal { }

class ByName : IComparer<Animal> {
    public int Compare(Animal x, Animal y) { return string.Compare(x.Name, y.Name); }
}

class Program {
    static void Main() {
        // Covariance: IEnumerable<out T> produces T
        IEnumerable<Dog> dogs = new List<Dog> { new Dog() };
        IEnumerable<Animal> animals = dogs;
        Console.WriteLine("covariant ok, count = " + new List<Animal>(animals).Count);
        // Contravariance: IComparer<in T> consumes T
        IComparer<Dog> cmp = new ByName();     // IComparer<Animal> used as IComparer<Dog>
        Console.WriteLine("contravariant compare = " + cmp.Compare(new Dog(), new Dog()));
        Action<Animal> act = a => Console.WriteLine("acting on " + a.Name);
        Action<Dog> dogAct = act;               // contravariant delegate
        dogAct(new Dog());
        // Arrays are covariant but checked at run time
        Animal[] arr = new Dog[1];
        try { arr[0] = new Animal(); } catch (ArrayTypeMismatchException) { Console.WriteLine("array covariance: ArrayTypeMismatchException"); }
        // List<Animal> l = new List<Dog>();  // would not compile: List<T> is invariant
    }
}

using System;

// C# 11 syntax would be: interface IMonoid<T> where T : IMonoid<T> { static abstract T Zero { get; } ... }
// Closest C# 7 equivalent: a "witness" object that supplies the operations to generic code.
interface IMonoid<T> { T Zero { get; } T Add(T a, T b); }

class IntSum : IMonoid<int> {
    public int Zero { get { return 0; } }
    public int Add(int a, int b) { return a + b; }
}
class StrConcat : IMonoid<string> {
    public string Zero { get { return ""; } }
    public string Add(string a, string b) { return a + b; }
}

class Program {
    // One generic algorithm for every type that has a Zero and an Add
    static T Sum<T, M>(T[] xs) where M : IMonoid<T>, new() {
        M m = new M();
        T acc = m.Zero;
        foreach (T x in xs) acc = m.Add(acc, x);
        return acc;
    }
    static void Main() {
        Console.WriteLine("ints:    " + Sum<int, IntSum>(new[] { 1, 2, 3, 4 }));
        Console.WriteLine("strings: " + Sum<string, StrConcat>(new[] { "a", "b", "c" }));
    }
}

using System;
using System.Collections.Generic;

class Greeter { public string Hello() { return "instance Hello"; } }

static class Ext {
    public static string Hello(this Greeter g) { return "extension Hello"; }   // never called: instance wins
    public static string Shout(this string s) { return s == null ? "<null>" : s.ToUpper() + "!"; }
    public static string Describe(this object o) { return "object:" + o.GetType().Name; }
}

class Program {
    static void Main() {
        Console.WriteLine(new Greeter().Hello());          // instance method beats the extension
        string s = null;
        Console.WriteLine(s.Shout());                      // null receiver is allowed
        Console.WriteLine("hey".Shout());
        object o = "text";                                 // static type decides, no polymorphism
        Console.WriteLine(o.Describe());
        Console.WriteLine(Ext.Hello(new Greeter()));       // explicit call shows the shadowed one
    }
}

using System;

class Money : IEquatable<Money> {
    public readonly decimal Amount;
    public Money(decimal a) { Amount = a; }
    public static Money operator +(Money a, Money b) { return new Money(a.Amount + b.Amount); }
    public static bool operator ==(Money a, Money b) {
        if (ReferenceEquals(a, null)) return ReferenceEquals(b, null);   // avoid infinite recursion
        return a.Equals(b);
    }
    public static bool operator !=(Money a, Money b) { return !(a == b); } // pairs come together
    public bool Equals(Money o) { return !ReferenceEquals(o, null) && Amount == o.Amount; }
    public override bool Equals(object o) { return Equals(o as Money); }
    public override int GetHashCode() { return Amount.GetHashCode(); }    // must agree with ==
    public static implicit operator Money(decimal d) { return new Money(d); } // lossless: implicit ok
    public static explicit operator decimal(Money m) { return m.Amount; }
    public override string ToString() { return "$" + Amount; }
}

class Program {
    static void Main() {
        Money a = 5m, b = 7.5m;
        Console.WriteLine(a + " + " + b + " = " + (a + b));
        Console.WriteLine("equal? " + (a + b == new Money(12.5m)));
        Console.WriteLine("null? " + (a == null));
        object oa = a, ob = new Money(5m);
        Console.WriteLine("through object: Equals " + oa.Equals(ob) + ", == " + (oa == ob));
    }
}

using System;
using System.Linq.Expressions;

class Program {
    static string Walk(Expression e) {
        var b = e as BinaryExpression;
        if (b != null) return "(" + Walk(b.Left) + " " + b.NodeType + " " + Walk(b.Right) + ")";
        var m = e as MemberExpression;
        if (m != null) return m.Member.Name;           // property or captured field
        var c = e as ConstantExpression;
        if (c != null) return c.Value.ToString();
        return e.NodeType.ToString();
    }
    static void Main() {
        int min = 18;
        Expression<Func<int, bool>> pred = age => age > min && age < 65;
        Console.WriteLine("body type : " + pred.Body.NodeType);
        Console.WriteLine("tree      : " + Walk(pred.Body));   // a provider would turn this into SQL
        Func<int, bool> f = pred.Compile();                    // tree -> delegate at run time
        Console.WriteLine("f(30) = " + f(30) + ", f(10) = " + f(10));
        // Property name from a lambda: the classic use
        Expression<Func<string, int>> len = s => s.Length;
        Console.WriteLine("member    : " + ((MemberExpression)len.Body).Member.Name);
    }
}

using System;
using System.Diagnostics;
using System.Reflection;

class Point { public int X { get; set; } }

class Program {
    static void Main() {
        var p = new Point { X = 1 };
        PropertyInfo pi = typeof(Point).GetProperty("X");              // cache this, do not look up per call
        // MethodInfo -> typed delegate: delegate speed after one-time setup
        Func<Point, int> getter = (Func<Point, int>)Delegate.CreateDelegate(typeof(Func<Point, int>), pi.GetGetMethod());
        const int N = 2000000;
        long sum = 0;
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < N; i++) { p.X = i; sum += (int)pi.GetValue(p); }
        long reflMs = sw.ElapsedMilliseconds;
        sw.Restart();
        for (int i = 0; i < N; i++) { p.X = i; sum += getter(p); }
        long delMs = sw.ElapsedMilliseconds;
        Console.WriteLine("both loops computed the same sum: " + (sum % 2 == 0));
        Console.WriteLine("timings are machine dependent, so they are not printed");
        Console.WriteLine("getter(p) = " + getter(p));
    }
}

using System;

struct Pair { public int A, B; }                 // value type, no references: "unmanaged"

class Widget { public Widget() { } public override string ToString() { return "Widget"; } }

class Program {
    static T Make<T>() where T : new() { return new T(); }
    static T Factory<T>(Func<T> f) { return f(); }           // faster than new T()
    static bool IsNull<T>(T v) where T : class { return v == null; }   // class: reference type
    static int Size<T>() where T : struct { return System.Runtime.InteropServices.Marshal.SizeOf(typeof(T)); }
    // 'where T : notnull' (C# 8) is not available here; it would mean any non-nullable type

    static void Main() {
        Console.WriteLine(Make<Widget>());
        Console.WriteLine(Factory<Widget>(() => new Widget()));
        Console.WriteLine("IsNull(string null) = " + IsNull<string>(null));
        Console.WriteLine("Size<Pair> = " + Size<Pair>());
        int? n = 3;                                          // T? with struct constraint means Nullable<T>
        Console.WriteLine("Nullable<int> has value: " + n.HasValue);
    }
}

using System;
using System.Collections.Generic;

interface IA { } interface IB { }
class B : IB { public B() { Console.WriteLine("  new B"); } }
class A : IA { public A(IB b) { Console.WriteLine("  new A(B)"); } }
class X : IA { public X(IA a) { } }   // cycle demo: X needs IA, IA is X

class Container {
    class Reg { public Type Impl; public bool Singleton; public object Cache; }
    Dictionary<Type, Reg> regs = new Dictionary<Type, Reg>();
    public void Add<TS, TI>(bool singleton) { regs[typeof(TS)] = new Reg { Impl = typeof(TI), Singleton = singleton }; }
    public object Resolve(Type t) { return Resolve(t, new List<Type>()); }
    object Resolve(Type t, List<Type> path) {
        if (path.Contains(t)) {                                   // cycle detection
            path.Add(t);
            throw new InvalidOperationException("cycle: " + string.Join(" -> ", path.ConvertAll(x => x.Name).ToArray()));
        }
        Reg r = regs[t];
        if (r.Singleton && r.Cache != null) return r.Cache;
        path.Add(t);
        var ctor = r.Impl.GetConstructors()[0];                   // recursion on constructor parameters
        var args = new List<object>();
        foreach (var p in ctor.GetParameters()) args.Add(Resolve(p.ParameterType, path));
        path.RemoveAt(path.Count - 1);
        object o = ctor.Invoke(args.ToArray());
        if (r.Singleton) r.Cache = o;
        return o;
    }
}

class Program {
    static void Main() {
        var c = new Container();
        c.Add<IB, B>(true); c.Add<IA, A>(false);
        Console.WriteLine("first:");  c.Resolve(typeof(IA));
        Console.WriteLine("second (B is singleton, so no new B):"); c.Resolve(typeof(IA));
        var bad = new Container(); bad.Add<IA, X>(false);
        try { bad.Resolve(typeof(IA)); } catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}

using System;
using System.Collections.Generic;

class Animal { public virtual string Name { get { return "animal"; } } }
class Dog : Animal { public override string Name { get { return "dog"; } } }
class Cat : Animal { public override string Name { get { return "cat"; } } }

class Program {
    // Read-only, covariant parameter: callers may pass List<Dog> or Dog[]
    static void PrintAll(IReadOnlyList<Animal> items) {
        foreach (Animal a in items) Console.Write(a.Name + " ");
        Console.WriteLine("(" + items.Count + ")");
    }
    // Writing needs a generic method so the element type stays exact
    static void AddTwo<T>(ICollection<T> target, T x, T y) where T : Animal { target.Add(x); target.Add(y); }

    static void Main() {
        var dogs = new List<Dog> { new Dog() };
        PrintAll(dogs);                         // List<Dog> -> IReadOnlyList<Animal> works
        AddTwo(dogs, new Dog(), new Dog());     // T = Dog, so a Cat would not compile
        PrintAll(dogs);
        // The danger an invariant List<T> prevents:
        // List<Animal> bad = dogs; bad.Add(new Cat());  // compile error CS0029
        var animals = new List<Animal>();
        AddTwo(animals, new Dog(), new Cat());
        PrintAll(animals);
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;

[AttributeUsage(AttributeTargets.Property)]
sealed class RuleAttribute : Attribute {
    public static int Created = 0;                 // counts how many attribute objects get built
    public RuleAttribute() { Created++; }
}

class Order { [Rule] public int Qty { get; set; } [Rule] public int Price { get; set; } }

static class Meta {
    static Dictionary<Type, PropertyInfo[]> cache = new Dictionary<Type, PropertyInfo[]>();
    public static PropertyInfo[] RuleProps(Type t) {
        PropertyInfo[] r;
        if (cache.TryGetValue(t, out r)) return r;      // later calls: no reflection work
        var list = new List<PropertyInfo>();
        foreach (var p in t.GetProperties())
            if (Attribute.IsDefined(p, typeof(RuleAttribute))) list.Add(p);  // IsDefined builds no attribute
        return cache[t] = list.ToArray();
    }
}

class Program {
    static void Main() {
        for (int i = 0; i < 1000; i++)
            foreach (var p in typeof(Order).GetProperties()) p.GetCustomAttributes(typeof(RuleAttribute), false);
        Console.WriteLine("uncached, 1000 requests, attribute objects built: " + RuleAttribute.Created);
        RuleAttribute.Created = 0;
        for (int i = 0; i < 1000; i++) Meta.RuleProps(typeof(Order));
        Console.WriteLine("cached,   1000 requests, attribute objects built: " + RuleAttribute.Created);
        Console.WriteLine("properties with a rule: " + Meta.RuleProps(typeof(Order)).Length);
    }
}
